OPENING_BACKGROUNDS = {
    '春晓': ('唐代孟浩然常写山水和乡间生活。这首五言绝句从睡醒听见鸟声写起，又回想昨夜的风雨，惦记院外的花。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/春曉_(孟浩然)'),
    '登鹳雀楼': ('这首唐代五言绝句通行署名王之涣。登楼的人先看落日和黄河，再想到向上走一层，可以望得更远。“入海流”写黄河奔向大海，并非登楼就看见了海。具体创作年月不详。', 'https://zh.wikisource.org/wiki/登鸛雀樓_(王之渙)'),
    '悯农·其二': ('唐代李绅的《悯农》组诗关心种粮人的辛苦，本课是写锄禾的完整一首：烈日下劳作的汗水，换来了盘中的饭粒。“悯”是体恤、关心的意思。具体创作年月、地点不详。', 'https://rw.zjnu.edu.cn/_upload/article/files/0b/61/2d54affb4443a594305bf9ecea79/18144959-03b8-45eb-a83f-40fbe4b3da1b.pdf'),
    '风': ('唐代李峤把看不见的风写成能做许多事的主角：吹落秋叶，带来春花，掀起江浪，吹弯竹子。这是咏物诗，用周围事物的变化让人感到风的力量。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/風_(李嶠)'),
    '池上': ('这首是唐代白居易《池上二绝》的其二。组诗一首写池边下棋，一首写小娃划艇采莲；小娃想悄悄回来，水面的浮萍却留下了一条路。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/池上二絕'),
    '江雪': ('唐代柳宗元写下这首五言绝句：大雪让山路和江面显得格外安静，广阔天地中只剩一位戴斗笠、披蓑衣的老人独自垂钓。雪景带着清冷和孤独，也显出人物的坚持。具体创作年月、江名不详。', 'https://zh.wikisource.org/wiki/江雪'),
    '寻隐者不遇': ('这首唐诗通行署名贾岛，古籍也保存了孙革的异署。拜访者来到松下，向童子打听老师；童子知道老师去山中采药，却不知道他在云深处的哪里。诗中的问答没有交代最终见到了人。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/尋隱者不遇'),
    '鹿柴': ('这是唐代王维《辋川集》中的一首。组诗以各处山水景物为题，鹿柴这一处先传来人的声音，接着夕阳照进深林，落在青苔上。短短四句让安静的山林有了声音和光。具体创作年月不详。', 'https://zh.wikisource.org/wiki/輞川集_(王維)#鹿柴'),
    '鸟鸣涧': ('王维把这首诗收入题为《皇甫岳云溪杂题五首》的组诗中。春夜里人心安静，花落、月升和几声鸟鸣都变得清楚；微小的动静衬出了山涧的幽静。具体写作年月及云溪的确切地点尚未确证。', 'https://zh.wikisource.org/wiki/皇甫嶽雲溪雜題五首/鳥鳴澗'),
    '竹里馆': ('唐代王维的《辋川集》用二十首短诗写不同山水景物，竹里馆是其中一处。一个人坐在竹林中弹琴、长啸，周围无人知晓他的心情，明月却静静照着他。具体创作年月不详。', 'https://zh.wikisource.org/wiki/輞川集_(王維)#竹里館'),
    '相思': ('唐代王维用南方生长的红豆写牵挂。诗中向“君”说话，请对方多采一些红豆，用小小的果实寄托思念；被思念者的身份没有在这首诗里写明。具体创作年月、地点不详。', 'https://zh.wikisource.org/wiki/相思'),
    '小儿垂钓': ('唐人笔记《云溪友议》等古籍保存了胡令能这首诗。一个刚学钓鱼的孩子侧坐草间，遇到问路的人，怕说话惊走鱼，便远远招手回应。诗写出了孩子专注又有趣的神态。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/小兒垂釣'),
    '绝句·两个黄鹂鸣翠柳': ('唐代杜甫把近处的柳树和黄鹂、天上的白鹭、远处的雪山与门前的船写进一幅明亮的画面。窗和门好像画框，让目光从近处走向远方。“千秋”“万里”使景象开阔。具体创作年月未确证。', 'https://zh.wikisource.org/wiki/絕句_(兩個黃鸝鳴翠柳)'),
    '绝句·迟日江山丽': ('这是唐代杜甫写春景的五言绝句。日照变得暖和，花草散出香气，燕子忙着飞，鸳鸯安静地睡；动与静合在一起，表现春天的生机和安宁。具体写作年月未确证。', 'https://zh.wikisource.org/wiki/絕句（遲日江山麗）'),
    '咏柳': ('唐代贺知章写的是初春柳树：新叶像碧玉，垂下的柳条像丝带。诗人忽然问，细叶是谁裁出来的，又把春风想成一把剪刀。这样的想象是在赞美春天巧妙地带来新生命。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/詠柳_(賀知章)'),
    '回乡偶书·其一': ('唐代贺知章写了两首《回乡偶书》，这首从“少小离家老大回”写自己的久别归乡。口音仍熟悉，鬓发已变老；家乡的孩子把归来者当作客人，亲切的问话也让人感到岁月流逝。具体写作日子不详。', 'https://zh.wikisource.org/wiki/回鄉偶書二首'),
    '九月九日忆山东兄弟': ('唐代王维在这首诗中写重阳节的思亲。古人过重阳有登高、佩茱萸的习俗；他身在异乡，想象兄弟一起登高时会发现少了自己。诗题的“山东”是山以东的古代地域称呼。具体写作地点未确证。', 'https://zh.wikisource.org/wiki/九月九日憶山東兄弟'),
    '游子吟': ('唐代孟郊用一件临行前缝好的衣服写母亲的关爱。针脚密密，是母亲担心孩子迟迟不归；末尾把孩子比作小草，把母爱比作春天的阳光，感叹难以报答。具体写作年月未确证。', 'https://zh.wikisource.org/wiki/遊子吟_(孟郊)'),
    '望庐山瀑布': ('李白的《望庐山瀑布》有两首，本课是完整的七言绝句其二。诗题和首句指向庐山香炉峰一带的瀑布；阳光照着水雾，远望的飞瀑让诗人想到了从高天落下的银河。具体写作年月有不同考证。', 'https://zh.wikisource.org/wiki/望廬山瀑布#其二'),
    '早发白帝城': ('这首李白的唐诗又题《下江陵》。清晨的白帝城、两岸的猿声和层层山峰围绕着一条飞快行进的小舟，写出旅途轻快的感受。创作年代存在青年出蜀与晚年遇赦两种主要说法，未确证。', 'https://www.edb.gov.hk/attachment/tc/curriculum-development/kla/chi-edu/resources/primary/lang/pdp/20250110_PDF.pdf'),
    '独坐敬亭山': ('唐代李白在这首诗中独坐望山。鸟儿飞远，云也飘走，敬亭山却一直在眼前；诗人把山想成一位相看不厌的朋友。拟人的山陪伴着独坐的人。具体创作年月不详。', 'https://zh.wikisource.org/wiki/獨坐敬亭山'),
    '山行': ('唐代杜牧写秋日山路上的所见：石径向上，白云间有人家，而晚秋枫林让行路人停下车来。“坐”在这里是“因为”，说明停车的缘由。“白云生处”有“深处”的古本异文。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/山行_(杜牧)'),
    '清明': ('《千家诗》保存了这首通行署名杜牧的唐诗。清明时节，雨中的行人心情低落，便向牧童问路；牧童指向远处的杏花村。诗中的村名不足以确定今天某一处旅游地点，具体创作年月、地点不详。', 'https://zh.wikisource.org/wiki/清明_(杜牧)'),
    '赠汪伦': ('《全唐诗》题下注记李白游泾县桃花潭，汪伦曾用酒招待他。诗写李白将要乘舟离开，忽然听见岸上的踏歌送别；潭水再深，也比不上朋友的情意。具体送别日子不详。', 'https://zh.wikisource.org/wiki/贈汪倫'),
    '望天门山': ('唐代李白在这首诗中望见隔江相对的天门山。江水从两山间穿过，青山与一片孤帆让视线不断移动，写出了开阔有力的江景。题中的天门山与“楚江”构成地点线索；具体写作年月未确证。', 'https://zh.wikisource.org/wiki/望天門山'),
    '赋得古原草送别': ('唐代白居易这首诗共有八句，既写原野小草枯荣再生，也写送别朋友。前半的小草顽强，后半的青草沿古道伸向远方，让离情更深；常见只选四句的《草》节本并非完整全诗。具体写作年月未确证。', 'https://zh.wikisource.org/wiki/賦得古原草送別'),
    '江畔独步寻花·其六': ('唐代杜甫《江畔独步寻花七绝句》写沿江赏花的不同画面，本课是完整其六。花铺满黄四娘家旁的小路，蝴蝶留恋，黄莺啼叫，人的欢喜藏在热闹的春景里。黄四娘的详细身份与具体写作日子不详。', 'https://zh.wikisource.org/wiki/江畔獨步尋花七絕句'),
    '宿建德江': ('唐代孟浩然写旅途中在建德江边泊船的一夜。日暮让客居的愁绪重新涌起，远野里的天空显得低，清江上的月亮显得近；景色陪伴着想家的旅人。具体创作年月不详。', 'https://zh.wikisource.org/wiki/宿建德江'),
    '问刘十九': ('唐代白居易把这首短诗写成给朋友刘十九的邀请。新酿的酒已经备好，红泥炉暖着，天色看起来将要下雪，于是问朋友能否前来相聚。“十九”是古人称呼中的排行。具体写作年月、地点不详。', 'https://zh.wikisource.org/wiki/問劉十九'),
    '终南望余雪': ('唐代祖咏远望终南山积雪，由晴光想到城里傍晚的寒意。《全唐诗》题下注记记载了一个旧故事：他应试作了四句，认为意思已说完。这一记载不能确定具体考试日子。', 'https://zh.wikisource.org/wiki/終南望餘雪'),
    '如梦令·昨夜雨疏风骤': ('宋代李清照用一段问答写爱惜春花的心情。昨夜风急雨疏，清晨她惦记海棠，卷帘的人说花还照旧，她却想到叶子更茂、花朵更少。“如梦令”是词牌名。具体创作年月、地点未确证。', 'https://zh.wikisource.org/wiki/如夢令_(李清照)/如夢令_(昨夜雨疏風驟)'),
    '破阵子·燕子来时新社': ('宋代晏殊这首词把春天的景物和年轻人的游戏写在一起。燕子、梨花点出春社到清明的时节，随后出现采桑、斗草的快乐。“破阵子”是词牌名，作品写的却是轻快春景。具体创作年月、地点不详。', 'https://www.gushiwen.cn/gushiwen_99548c0eea.aspx'),
    '卜算子·咏梅': ('南宋陆游在这首咏物词中写驿站外断桥边的梅花。它在黄昏风雨中独自开放，不争春，花落以后仍留下香气；这样的梅寄托了不随处境改变品格的心意。具体创作年月、地点未确证。', 'https://zh.wikisource.org/wiki/卜算子_(陸游)'),
    '浣溪沙·一曲新词酒一杯': ('北宋晏殊在旧亭台听新词，看夕阳和落花，想到时光留不住；归来的燕子又像是旧相识。“浣溪沙”是词牌名，花落与燕归把伤感和亲切放在一起。具体创作年月、地点不详。', 'https://zh.wikisource.org/wiki/浣溪沙_(晏殊)#浣溪沙_(一曲新詞酒一杯)'),
}


def han(text: str) -> str:
    return "".join(HAN.findall(text))


def split_lines(text: str) -> list[str]:
    return [x.strip() for x in re.findall(r"[^，。！？；]+[，。！？；]?", text) if x.strip()]


def clean_text(text: str) -> str:
    # Upstream carries textual-variant notes inside paragraphs. Those belong in an
    # edition apparatus, not in the poem that the child hears or memorizes.
    return re.sub(r'\([^)]*\)|（[^）]*）', '', CC.convert(text)).strip()


def pronounce(text: str) -> list[str]:
    # Keep punctuation in the source text; syllables correspond only to Han characters.
    return lazy_pinyin(han(text), style=Style.TONE, neutral_tone_with_five=False, errors="default")


def E(title, author, text, theme, icon, interpretation, activity, prompt, correct, wrong, explanation, keywords, *, dynasty="唐", kind="诗", background="", url=""):
    return dict(title=title, author=author, dynasty=dynasty, kind=kind, lines=split_lines(text),
                theme=theme, icon=icon, interpretation=interpretation.split("|"), activity=activity,
                question=dict(prompt=prompt, options=[correct, wrong], answer=0, explanation=explanation),
                keywords=keywords.split("、"), background=background, backgroundSource=url, reviewStatus="edited")


