def C(title, author, theme, icon, background, interpretation, activity, prompt, correct, wrong, explanation, keywords, level=2, reviewStatus='edited', **extra):
    """An individually edited existing work, keyed before display-title disambiguation."""
    return (title, author), dict(theme=theme, icon=icon, background=background,
                                interpretation=interpretation.split('|'), activity=activity,
                                question=dict(prompt=prompt, options=[correct, wrong], answer=0, explanation=explanation),
                                keywords=keywords.split('、'), level=level, reviewStatus=reviewStatus, **extra)


