def normalize_sources():
    tang = []
    for item in json.loads((SOURCE / "tang300.json").read_text())['content']:
        for poem in item['content']:
            tang.append(dict(title=CC.convert(poem['subchapter'] or poem['chapter']).split(' / ')[0],
                             author=CC.convert(poem['author']), dynasty='唐', kind='诗',
                             lines=[clean_text(line) for line in poem['paragraphs']], source=TANG_URL))
    # Only explicit Tang annotations are included; known source errors are corrected below.
    for item in json.loads((SOURCE / "qianjiashi.json").read_text())['content']:
        for poem in item['content']:
            author = CC.convert(poem['author'])
            if '（唐）' not in author:
                continue
            if '谢枋得' in author:
                # Upstream incorrectly labels a Southern Song author as Tang.
                # This curriculum reserves Song entries for actual Song ci.
                continue
            author = author.replace('张佑', '张祜')
            # The anthology has nested multi-poem groups, some with misnumbered subchapters.
            # Do not flatten those into an invented single complete work.
            if not all(isinstance(line, str) for line in poem['paragraphs']):
                continue
            tang.append(dict(title=CC.convert(poem['chapter']), author=author.replace('（唐）', ''),
                             dynasty='唐', kind='诗', lines=[clean_text(line) for line in poem['paragraphs']], source=QIAN_URL))
    song = []
    for poem in json.loads((SOURCE / 'song300.json').read_text()):
        # Historical attribution errors/duplicates in upstream are excluded rather than silently repeated.
        if poem['author'] == '王安石' and poem['paragraphs'][0] == '留春不住。':
            continue
        title = CC.convert(poem['rhythmic']).replace('・', '·')
        first = split_lines(CC.convert(poem['paragraphs'][0]))[0].rstrip('，。！？；')
        song.append(dict(title=f'{title}·{first}', author=CC.convert(poem['author']), dynasty='宋', kind='词',
                         lines=[clean_text(line) for line in poem['paragraphs']], source=SONG_URL))
    return tang, song


